<script>
const products = @json($products);
const formatIDR = value => new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(value); let favorites = JSON.parse(localStorage.getItem('kastore_favorites') || '[]'); let activeFilter = 'ALL'; const grid = document.getElementById('product-grid'); const isAuthenticated = @json(auth()->check()); const buyUrlTemplate = @json(route('orders.store', ['product' => '__PRODUCT_ID__'], false));
function renderProducts() { const query = document.getElementById('search-input').value.toLowerCase(); const filtered = products.filter(product => (activeFilter === 'ALL' || (activeFilter === 'FAVORIT' ? favorites.includes(product.id) : product.category === activeFilter)) && product.name.toLowerCase().includes(query)); document.getElementById('empty-state').classList.toggle('hidden', filtered.length > 0); grid.classList.toggle('hidden', filtered.length === 0); grid.innerHTML = filtered.map(product => `<article class="group overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-soft transition hover:-translate-y-1 hover:border-blue-200"><div class="relative aspect-square overflow-hidden bg-[#${product.color}]"><img src="https://placehold.co/500x500/${product.color}/ffffff?text=${encodeURIComponent(product.name.split(' ')[0])}" alt="${product.name}" class="h-full w-full object-cover transition duration-500 group-hover:scale-105"><button type="button" onclick="toggleFavorite(${product.id})" aria-label="Toggle favorit" class="absolute right-2 top-2 grid h-8 w-8 place-items-center rounded-full bg-white/95 text-sm ${favorites.includes(product.id)?'text-rose-500':'text-slate-400'}"><i class="fa-${favorites.includes(product.id)?'solid':'regular'} fa-heart"></i></button></div><div class="p-3 sm:p-4"><div class="flex items-center justify-between gap-2"><span class="truncate text-[10px] font-bold uppercase tracking-wider text-electric">${product.category}</span><span class="shrink-0 text-[10px] text-slate-400">${product.stock} tersedia</span></div><h3 class="mt-2 line-clamp-2 min-h-[40px] font-display text-sm font-bold text-ink">${product.name}</h3><div class="mt-3"><strong class="font-display text-base text-ink">${formatIDR(product.price)}</strong></div><button type="button" onclick="checkout(${product.id})" ${product.stock && isAuthenticated?'':'disabled'} class="mt-4 w-full rounded-lg py-2.5 text-xs font-bold transition ${product.stock && isAuthenticated?'bg-electric text-white hover:bg-blue-700':'cursor-not-allowed bg-slate-100 text-slate-400'}">${!isAuthenticated?'Masuk untuk membeli':product.stock?'<i class="fa-solid fa-cart-shopping mr-1"></i> Beli sekarang':'Stok habis'}</button></div></article>`).join(''); }
const renderCatalog = renderProducts; renderProducts = () => { renderCatalog(); [...grid.children].forEach((card, index) => { const product = products.find(item => item.id === Number(card.querySelector('button[onclick^="checkout"]')?.getAttribute('onclick')?.match(/\d+/)?.[0])); if (!product) return; const meta = document.createElement('div'); meta.className = 'mt-2 flex items-center gap-1 text-[11px] text-amber-500'; meta.setAttribute('aria-label', 'Rating 5 dari 5'); meta.innerHTML = `<span aria-hidden="true">★★★★★</span><span class="text-slate-400">5.0 · ${new Intl.NumberFormat('id-ID').format(product.sold)}+ terjual</span>`; card.querySelector('h3')?.after(meta); }); }; window.toggleFavorite = id => { favorites = favorites.includes(id) ? favorites.filter(item => item !== id) : [...favorites,id]; localStorage.setItem('kastore_favorites',JSON.stringify(favorites)); renderProducts(); }; window.checkout = id => { if (!isAuthenticated) { window.location.href = @json(route('login', [], false)); return; } const form = document.createElement('form'); form.method = 'POST'; form.action = buyUrlTemplate.replace('__PRODUCT_ID__', id); form.innerHTML = `<input type="hidden" name="_token" value="${document.querySelector('meta[name=csrf-token]').content}">`; document.body.appendChild(form); form.submit(); };
document.querySelectorAll('.filter-btn').forEach(button => button.addEventListener('click', () => { activeFilter = button.dataset.filter; document.querySelectorAll('.filter-btn').forEach(item => item.className = item === button ? 'filter-btn shrink-0 rounded-lg bg-ink px-4 py-2.5 text-sm font-bold text-white' : 'filter-btn shrink-0 rounded-lg border border-slate-200 bg-white px-4 py-2.5 text-sm font-semibold text-slate-500'); renderProducts(); })); document.getElementById('search-input').addEventListener('input',renderProducts); document.getElementById('mobile-menu-btn').addEventListener('click',event => { const menu = document.getElementById('mobile-menu'); const isOpen = !menu.classList.toggle('hidden'); event.currentTarget.setAttribute('aria-expanded',isOpen); event.currentTarget.innerHTML = `<i class="fa-solid fa-${isOpen?'xmark':'bars'}"></i>`; }); renderProducts();
document.getElementById('invoice-form').addEventListener('submit', event => { event.preventDefault(); const result = document.getElementById('invoice-result'); const invoice = document.getElementById('invoice-input').value.toUpperCase(); result.className = 'mt-3 rounded-xl px-4 py-3 text-sm'; if (invoice === 'TL-240801') { result.classList.add('bg-emerald-50','text-emerald-700'); result.textContent = 'Invoice ditemukan. Pesanan Netflix Premium sedang diproses.'; } else { result.classList.add('bg-amber-50','text-amber-700'); result.textContent = 'Invoice belum ditemukan. Periksa kembali format dan nomor invoice Anda.'; } });
</script>
@endpush
